"""Write internal/rx/casetable.go from the running CPython's re case tables.

Run from the repo root: nix develop --impure -c python tools/rx/gen_casetable.py
"""

import sys
from re import _casefix

import _sre

OUT = "internal/rx/casetable.go"


def upper(c):
    return ord(chr(c).upper()[0])


def main():
    rows = []
    for c in range(sys.maxunicode + 1):
        if not _sre.unicode_iscased(c):
            continue
        lo = _sre.unicode_tolower(c)
        assert lo == ord(chr(c).lower()[0]), hex(c)
        rows.append((c, lo, upper(c)))
    out = [
        "// Code generated by tools/rx/gen_casetable.py; DO NOT EDIT.",
        "",
        "package rx",
        "",
        f"// pyCased lists every code point CPython {sys.version_info.major}.{sys.version_info.minor} re treats as cased"
        " (Unicode {}) with the lower and upper forms re uses: sorted by code point.".format(
            __import__("unicodedata").unidata_version
        ),
        "var pyCased = [...]casedRune{",
    ]
    out += [f"\t{{0x{c:04x}, 0x{lo:04x}, 0x{up:04x}}}," for c, lo, up in rows]
    out += [
        "}",
        "",
        "// caseFixes is re._casefix._EXTRA_CASES: lowercase characters that match further lowercase characters",
        "// under IGNORECASE because they share an uppercase form.",
        "var caseFixes = map[rune][]rune{",
    ]
    for k, v in sorted(_casefix._EXTRA_CASES.items()):
        out.append(f"\t0x{k:04x}: {{{', '.join(f'0x{x:04x}' for x in v)}}},")
    out += ["}", ""]
    with open(OUT, "w", encoding="utf-8") as f:
        f.write("\n".join(out))


if __name__ == "__main__":
    main()
